function grab(text, start, ends) {
  const li = text.toLowerCase();
  const s = li.indexOf(start.toLowerCase());
  if (s < 0) return '';
  let from = s + start.length;
  while (from < text.length && (text[from] === ':' || text[from] === ' ')) from++;
  let end = text.length;
  for (const e of ends) { const ei = li.indexOf(e.toLowerCase(), from); if (ei >= 0 && ei < end) end = ei; }
  return text.slice(from, end).trim();
}
